<?php
$model = \MSC\CatalogArchive::current(); $spec = $model['spec']; $f = $model['filters']; global $wp_query;
$count = (int) $wp_query->found_posts; $page = max( 1, (int) get_query_var( 'paged', 1 ) ); $by_post = array(); foreach ( $model['records'] as $record ) { $by_post[ $record['mapping']['post_id'] ] = $record; }
$active = array_filter( array_intersect_key( $f, array_fill_keys( array( 'catalog_q', 'catalog_facet', 'catalog_year', 'catalog_platform' ), true ) ), 'strlen' );
?>
<section id="catalog-archive" class="catalog-archive archive-layout-<?php echo esc_attr( $spec['layout'] ); ?>" data-catalog-key="<?php echo esc_attr( $spec['key'] ); ?>">
    <nav class="archive-breadcrumbs" aria-label="Breadcrumb"><a href="<?php echo esc_url( home_url( '/' ) ); ?>">Home</a><span aria-hidden="true">/</span><span>Catalog</span></nav>
    <header class="archive-hero archive-heading">
        <div class="archive-hero-copy"><p class="archive-eyebrow"><?php echo esc_html( msc_screen_identity()['name'] ); ?> · Catalog</p><h1><?php echo esc_html( $spec['label'] ); ?></h1><p class="archive-description"><?php echo esc_html( $spec['description'] ); ?></p><div class="archive-total"><strong><?php echo esc_html( number_format_i18n( $model['total'] ) ); ?></strong><span><?php echo esc_html( 1 === $model['total'] ? ( 'people' === $spec['noun'] ? 'person' : rtrim( $spec['noun'], 's' ) ) : $spec['noun'] ); ?></span><?php if ( $model['years'] && $spec['date'] ) { ?><span class="archive-date-range"><?php echo esc_html( min( $model['years'] ) === max( $model['years'] ) ? min( $model['years'] ) : min( $model['years'] ) . '–' . max( $model['years'] ) ); ?></span><?php } ?></div></div>
        <?php if ( $model['next'] ) { $next = $model['next']; ?>
            <aside class="archive-spotlight"><span class="archive-spotlight-label">Next release</span><a href="<?php echo esc_url( \MSC\Presentation::url( $next ) ); ?>" class="archive-spotlight-title<?php echo 'msc_episode' === $next['type'] ? ' no-art' : ''; ?>"><?php if ( 'msc_episode' !== $next['type'] ) { echo \MSC\Presentation::image( $next, 'archive-spotlight-art', 'medium' ); } ?><span><time datetime="<?php echo esc_attr( $next['catalog_date'] ); ?>"><?php echo esc_html( msc_archive_date( $next['catalog_date'] ) ); ?></time><strong><?php echo esc_html( $next['data']['title'] ); ?></strong></span></a><a class="archive-calendar-link" href="<?php echo esc_url( \MSC\NetworkSites::calendar_url() ); ?>">View release calendar <?php echo msc_archive_arrow(); ?></a></aside>
            <?php echo \MSC\Attribution::collect( $next, array( 'title', 'release_date', 'premiere_date' ) ) . ( 'msc_episode' !== $next['type'] ? \MSC\Attribution::collect_image( $next ) : '' ); ?>
        <?php } else { ?>
            <aside class="archive-spotlight archive-directory-nav"><span class="archive-spotlight-label">Related catalogs</span><?php foreach ( array( 'msc_movie' => 'Movies', 'msc_show' => 'TV Shows', 'msc_person' => 'People', 'msc_game' => 'Video Games' ) as $type => $label ) { if ( $type !== $spec['type'] && \MSC\Schema::enabled( $type ) ) { echo '<a href="' . esc_url( get_post_type_archive_link( $type ) ) . '">' . esc_html( $label ) . msc_archive_arrow() . '</a>'; } } ?><a href="<?php echo esc_url( \MSC\NetworkSites::calendar_url() ); ?>">Release calendar <?php echo msc_archive_arrow(); ?></a></aside>
        <?php } ?>
    </header>
    <div class="catalog-controls"><form class="catalog-filter-form" role="search" method="get" action="<?php echo esc_url( $spec['url'] ); ?>" aria-label="Search and filter <?php echo esc_attr( $spec['label'] ); ?>">
        <?php $route = array(); parse_str( wp_parse_url( $spec['url'], PHP_URL_QUERY ) ?: '', $route ); foreach ( $route as $key => $value ) { if ( is_string( $value ) ) { echo '<input type="hidden" name="' . esc_attr( $key ) . '" value="' . esc_attr( $value ) . '">'; } } ?>
        <label class="catalog-search-label" for="catalog-query">Search <?php echo in_array( $spec['layout'], array( 'people', 'directory' ), true ) ? 'names' : 'titles'; ?><span class="catalog-search-input"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input type="search" name="catalog_q" id="catalog-query" value="<?php echo esc_attr( $f['catalog_q'] ); ?>" maxlength="160" placeholder="Search <?php echo esc_attr( strtolower( $spec['label'] ) ); ?>"></span></label>
        <?php if ( $model['facets'] ) { ?><label for="catalog-facet"><?php echo esc_html( $spec['facet_label'] ); ?><select name="catalog_facet" id="catalog-facet"><option value="">All <?php echo esc_html( 'country' === $spec['facet'] ? 'countries' : strtolower( $spec['facet_label'] ) . 's' ); ?></option><?php foreach ( $model['facets'] as $value => $label ) { echo '<option value="' . esc_attr( $value ) . '"' . selected( $f['catalog_facet'], (string) $value, false ) . '>' . esc_html( $label ) . '</option>'; } ?></select></label><?php } ?>
        <?php if ( $model['years'] && $spec['date'] ) { ?><label for="catalog-year">Release year<select name="catalog_year" id="catalog-year"><option value="">All years</option><?php foreach ( $model['years'] as $year ) { echo '<option value="' . esc_attr( $year ) . '"' . selected( $f['catalog_year'], (string) $year, false ) . '>' . esc_html( $year ) . '</option>'; } ?></select></label><?php } ?>
        <?php if ( $model['platforms'] ) { ?><label for="catalog-platform">Platform<select name="catalog_platform" id="catalog-platform"><option value="">All platforms</option><?php foreach ( $model['platforms'] as $platform ) { echo '<option value="' . esc_attr( $platform ) . '"' . selected( $f['catalog_platform'], $platform, false ) . '>' . esc_html( $platform ) . '</option>'; } ?></select></label><?php } ?>
        <label for="catalog-sort">Sort by<select name="catalog_sort" id="catalog-sort"><?php foreach ( $model['sorts'] as $value => $label ) { echo '<option value="' . esc_attr( $value ) . '"' . selected( $f['catalog_sort'], $value, false ) . '>' . esc_html( $label ) . '</option>'; } ?></select></label><button class="catalog-apply" type="submit">Apply filters <?php echo msc_archive_arrow(); ?></button>
    </form></div>
    <?php if ( $model['facets'] && 'type' !== $spec['facet'] ) { ?><nav class="catalog-quick-filters" aria-label="Browse by <?php echo esc_attr( strtolower( $spec['facet_label'] ) ); ?>"><span><?php echo esc_html( $spec['facet_label'] ); ?></span><?php foreach ( array_slice( $model['facets'], 0, 6, true ) as $value => $label ) { echo '<a class="catalog-filter-link" href="' . esc_url( \MSC\CatalogArchive::url( $model, array( 'catalog_facet' => (string) $value ) ) ) . '"' . ( (string) $value === $f['catalog_facet'] ? ' aria-current="page"' : '' ) . '>' . esc_html( $label ) . '</a>'; } ?></nav><?php } ?>
    <div id="catalog-results" class="catalog-results"><div class="catalog-result-bar"><p class="catalog-result-count" role="status"><?php echo esc_html( $count ? 'Showing ' . number_format_i18n( ( $page - 1 ) * \MSC\CatalogArchive::PAGE_SIZE + 1 ) . '–' . number_format_i18n( min( $count, $page * \MSC\CatalogArchive::PAGE_SIZE ) ) . ' of ' . number_format_i18n( $count ) : '0 results' ); ?></p><?php if ( $active ) { ?><a class="catalog-filter-link catalog-reset" href="<?php echo esc_url( $spec['url'] ); ?>">Reset filters</a><?php } ?></div>
        <p class="catalog-load-status" role="alert" hidden></p>
        <div class="catalog-grid archive-grid"><?php while ( have_posts() ) { the_post(); if ( isset( $by_post[ get_the_ID() ] ) ) { msc_archive_card( $by_post[ get_the_ID() ] ); } } if ( ! $count ) { ?><div class="catalog-empty"><h2><?php echo $active ? 'No matching results' : 'No published entries'; ?></h2><p><?php echo $active ? 'Try another search or change the filters.' : 'Published entries will appear in this catalog.'; ?></p><?php if ( $active ) { ?><a class="catalog-filter-link" href="<?php echo esc_url( $spec['url'] ); ?>">Reset filters <?php echo msc_archive_arrow(); ?></a><?php } ?></div><?php } ?></div>
        <div class="archive-pagination"><?php the_posts_pagination( array( 'mid_size' => 1, 'prev_text' => 'Previous', 'next_text' => 'Next' ) ); ?></div>
    </div>
</section>
